-- OPTIONAL. The application creates all of these automatically the first time they are used
-- (LiveExtras.php, SiteExtras.php, Star.php). Run this file only if you prefer to set up the
-- database by hand. All statements are safe to run more than once, except the ALTER at the end.

CREATE TABLE IF NOT EXISTS live_stage_state (live_id INT NOT NULL PRIMARY KEY, topic VARCHAR(255) NULL, pinned_message VARCHAR(500) NULL, shoutout VARCHAR(255) NULL, shoutout_until DATETIME NULL, version INT NOT NULL DEFAULT 0, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS live_polls (id INT AUTO_INCREMENT PRIMARY KEY, live_id INT NOT NULL, question VARCHAR(300) NOT NULL, status ENUM('open','closed') NOT NULL DEFAULT 'open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, closed_at DATETIME NULL, INDEX idx_live_polls_live (live_id, status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS live_poll_options (id INT AUTO_INCREMENT PRIMARY KEY, poll_id INT NOT NULL, label VARCHAR(160) NOT NULL, position INT NOT NULL DEFAULT 0, INDEX idx_live_poll_options_poll (poll_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS live_poll_votes (poll_id INT NOT NULL, user_id INT NOT NULL, option_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (poll_id, user_id), INDEX idx_live_poll_votes_option (option_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS live_questions (id INT AUTO_INCREMENT PRIMARY KEY, live_id INT NOT NULL, user_id INT NOT NULL, question VARCHAR(300) NOT NULL, status ENUM('open','answered','hidden') NOT NULL DEFAULT 'open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_live_questions_live (live_id, status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS live_question_votes (question_id INT NOT NULL, user_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (question_id, user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS live_presence (live_id INT NOT NULL, viewer_key VARCHAR(40) NOT NULL, user_id INT NULL, first_seen DATETIME NOT NULL, last_seen DATETIME NOT NULL, PRIMARY KEY (live_id, viewer_key), INDEX idx_live_presence_seen (live_id, last_seen)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS live_reaction_events (id BIGINT AUTO_INCREMENT PRIMARY KEY, live_id INT NOT NULL, emoji VARCHAR(16) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_live_reaction_events_live (live_id, id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS live_reminders (live_id INT NOT NULL, user_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, notified_at DATETIME NULL, PRIMARY KEY (live_id, user_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS movie_cast (movie_id INT NOT NULL, star_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (movie_id, star_id), INDEX idx_movie_cast_star (star_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS user_watchlist (user_id INT NOT NULL, movie_id INT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (user_id, movie_id), INDEX idx_watchlist_movie (movie_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

